python3 -c "
import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml') as f:
    reg = yaml.safe_load(f)

# The structure might be nested under 'experiments'
if 'experiments' in reg:
    exps = reg['experiments']
else:
    exps = reg

if isinstance(exps, dict):
    entries = [(rid, exp) for rid, exp in exps.items() if isinstance(exp, dict)]
    entries.sort(key=lambda x: str(x[1].get('created_at', '')), reverse=True)
    for rid, exp in entries[:25]:
        print(f'{rid}: status={exp.get(\"status\")}, conclusion={exp.get(\"conclusion\",\"\")}, created={str(exp.get(\"created_at\",\"?\"))[:19]}')
elif isinstance(exps, list):
    for exp in exps[-25:]:
        rid = exp.get('id', '?')
        print(f'{rid}: status={exp.get(\"status\")}, conclusion={exp.get(\"conclusion\",\"\")}')
"

